<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Premium Dark Site - QA</title>
    <style>
        :root {
            --bg-body: #0a0a0b;
            --bg-card: #111113;
            --text-main: #ffffff;
            --text-muted: #888890;
            --accent-red: #e50914;
            --border-color: #222225;
            --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
        }

        * {
            margin: 0;
            padding: 0;
            box-sizing: border-box;
        }

        body {
            background-color: var(--bg-body);
            color: var(--text-main);
            font-family: var(--font-sans);
            line-height: 1.5;
            -webkit-font-smoothing: antialiased;
        }

        /* --- Navigation --- */
        nav {
            display: flex;
            justify-content: space-between;
            align-items: center;
            padding: 20px 40px;
            border-bottom: 1px solid rgba(255,255,255,0.05);
            position: sticky;
            top: 0;
            background: rgba(10,10,11, 0.95);
            backdrop-filter: blur(10px);
            z-index: 100;
        }

        .logo {
            font-size: 12px;
            letter-spacing: 2px;
            text-transform: uppercase;
            color: var(--text-muted);
            display: flex;
            align-items: center;
            gap: 10px;
        }

        .logo::before {
            content: '';
            width: 16px;
            height: 4px;
            background-color: var(--accent-red);
            border-radius: 2px;
        }

        .nav-links {
            display: flex;
            gap: 30px;
            list-style: none;
        }

        .nav-links a {
            color: var(--text-main);
            text-decoration: none;
            font-size: 15px;
            opacity: 0.7;
            transition: opacity 0.3s;
            padding-bottom: 4px;
        }

        .nav-links a:hover, .nav-links a.active {
            opacity: 1;
        }

        .nav-links a.active {
            border-bottom: 2px solid var(--accent-red);
        }

        .nav-actions {
            display: flex;
            align-items: center;
            gap: 20px;
        }

        .admin-link {
            color: var(--text-muted);
            text-decoration: none;
            font-size: 13px;
            display: flex;
            align-items: center;
            gap: 6px;
        }

        .btn-dashboard {
            background: transparent;
            border: 1px solid #333;
            color: white;
            padding: 8px 18px;
            border-radius: 20px;
            cursor: pointer;
            font-size: 14px;
            transition: all 0.3s ease;
        }

        .btn-dashboard:hover {
            border-color: #555;
            background: rgba(255,255,255,0.05);
        }

        /* --- Main Content Layout --- */
        main {
            max-width: 1400px;
            margin: 0 auto;
            padding: 60px 40px;
            min-height: calc(100vh - 80px);
        }

        /* --- Section: About (The Studio) --- */
        .about-section {
            margin-bottom: 100px;
        }

        .cinematic-card {
            position: relative;
            width: 100%;
            height: 600px; /* Wide cinematic aspect */
            border-radius: 12px;
            overflow: hidden;
            border: 1px solid var(--border-color);
            box-shadow: 0 25px 80px rgba(0,0,0,0.5);
        }

        .photo-bg {
            width: 100%;
            height: 100%;
            object-fit: cover;
            /* Simulating the team photo with a gradient/placeholder if image fails, 
               but we will use a high quality unsplash image */
            filter: contrast(1.05) saturate(0.95);
        }

        .card-overlay {
            position: absolute;
            bottom: 0;
            left: 0;
            right: 0;
            height: 50%;
            background: linear-gradient(to top, rgba(0,0,0,0.9) 0%, rgba(0,0,0,0) 100%);
            padding: 60px;
            display: flex;
            flex-direction: column;
            justify-content: flex-end;
        }

        .label-kicker {
            font-size: 11px;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: #d4af37; /* Goldish tone */
            margin-bottom: 16px;
            font-weight: 700;
        }

        .card-headline {
            font-size: 42px;
            font-weight: 800;
            line-height: 1.1;
            max-width: 600px;
            letter-spacing: -1px;
        }

        /* --- Section: Security (Under The Shell) --- */
        .security-section {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 60px;
            align-items: center;
            min-height: 500px;
        }

        .security-content {
            z-index: 2;
        }

        .sec-label {
            font-size: 11px;
            letter-spacing: 3px;
            text-transform: uppercase;
            color: #d4af37;
            margin-bottom: 24px;
            font-weight: 700;
        }

        .sec-headline {
            font-size: 56px;
            font-weight: 800;
            line-height: 1.05;
            margin-bottom: 24px;
            letter-spacing: -1.5px;
        }

        .sec-desc {
            font-size: 18px;
            color: var(--text-muted);
            margin-bottom: 40px;
            max-width: 480px;
            line-height: 1.6;
        }

        .btn-cta {
            display: inline-flex;
            align-items: center;
            gap: 10px;
            background-color: var(--accent-red);
            color: white;
            padding: 16px 32px;
            border-radius: 50px;
            text-decoration: none;
            font-weight: 600;
            font-size: 16px;
            transition: transform 0.2s, box-shadow 0.2s;
            box-shadow: 0 10px 30px rgba(229, 9, 20, 0.3);
        }

        .btn-cta:hover {
            transform: translateY(-2px);
            box-shadow: 0 15px 40px rgba(229, 9, 20, 0.4);
        }

        .security-visual {
            position: relative;
            height: 500px;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* Abstract Red Shield/Cube Visual */
        .abstract-shield-container {
            width: 400px;
            height: 400px;
            position: relative;
            display: flex;
            justify-content: center;
            align-items: center;
        }

        .shield-glow {
            position: absolute;
            width: 300px;
            height: 300px;
            background: radial-gradient(circle, rgba(229,9,20,0.2) 0%, rgba(0,0,0,0) 70%);
            z-index: 0;
            animation: pulse 4s infinite ease-in-out;
        }

        .shield-shape {
            width: 200px;
            height: 240px;
            background: linear-gradient(135deg, #2a0000 0%, #500000 100%);
            clip-path: polygon(50% 0%, 100% 25%, 100% 75%, 50% 100%, 0% 75%, 0% 25%);
            position: relative;
            z-index: 1;
            box-shadow: 0 0 50px rgba(229, 9, 20, 0.2);
            border: 1px solid rgba(229, 9, 20, 0.3);
            display: flex;
            justify-content: center;
            align-items: center;
        }

        /* Inner cube/shield detail */
        .inner-cube {
            width: 80px;
            height: 80px;
            border: 2px solid rgba(255,255,255,0.2);
            transform: rotate(45deg);
            box-shadow: inset 0 0 20px rgba(229, 9, 20, 0.5);
        }

        /* Circuit lines decoration */
        .circuit-line {
            position: absolute;
            background: linear-gradient(90deg, transparent, rgba(229,9,20,0.5), transparent);
            height: 1px;
            width: 100%;
            top: 50%;
            left: 0;
            transform: scaleX(1.5);
            opacity: 0.5;
        }

        @keyframes pulse {
            0% { transform: scale(1); opacity: 0.5; }
            50% { transform: scale(1.1); opacity: 0.8; }
            100% { transform: scale(1); opacity: 0.5; }
        }

        /* Responsive */
        @media (max-width: 900px) {
            .security-section {
                grid-template-columns: 1fr;
                gap: 40px;
            }
            .security-visual {
                height: 350px;
                order: -1; /* Image on top for mobile usually, or keep bottom */
            }
            .card-headline, .sec-headline {
                font-size: 36px;
            }
            nav {
                padding: 15px 20px;
            }
            .nav-links {
                display: none; /* Simplified for demo */
            }
        }
    </style>
</head>
<body>

    <!-- Navigation -->
    <nav>
        <div class="logo">Communication</div>
        <ul class="nav-links">
            <li><a href="#">Product ▾</a></li>
            <li><a href="#">Solutions</a></li>
            <li><a href="#">Pricing</a></li>
            <li><a href="#" class="active">Security</a></li>
            <li><a href="#" class="active">About</a></li>
        </ul>
        <div class="nav-actions">
            <a href="#" class="admin-link">⌖ ADMIN</a>
            <button class="btn-dashboard">Open dashboard</button>
        </div>
    </nav>

    <main>
        <!-- SECTION 1: ABOUT PAGE (The Studio) -->
        <section class="about-section">
            <article class="cinematic-card">
                <!-- Photo Rendering: YES (Using Unsplash Team Photo) -->
                <img src="https://images.unsplash.com/photo-1522071820081-009f0129c71c?q=80&w=2070&auto=format&fit=crop" alt="The Studio Team" class="photo-bg">

                <div class="card-overlay">
                    <span class="label-kicker">THE STUDIO</span>
                    <h2 class="card-headline">Small, senior, allergic to hold music.</h2>
                </div>
            </article>
        </section>

        <!-- SECTION 2: SECURITY PAGE (Under The Shell) -->
        <section class="security-section">
            <div class="security-content">
                <span class="sec-label">UNDER THE SHELL</span>
                <h2 class="sec-headline">Security you can inspect, not just feel.</h2>
                <p class="sec-desc">Every claim on this page maps to a control in the code. Ask us to point at it.</p>
                <a href="#" class="btn-cta">
                    Start building free
                    <span>→</span>
                </a>
            </div>

            <div class="security-visual">
                <!-- Photo Rendering: ABSTRACT (CSS Composition simulating the red shield/cube) -->
                <div class="abstract-shield-container">
                    <div class="shield-glow"></div>
                    <div class="circuit-line"></div>
                    <div class="shield-shape">
                        <div class="inner-cube"></div>
                    </div>
                </div>
            </div>
        </section>
    </main>

</body>
</html>
```
